const input=$json.body??$json;
const verified=input.verified_close??{};
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const identityComplete=Boolean(input.deal_id&&input.lead_id&&input.property_id&&input.close_id);
const verifiedClose=verified.verified===true||verified.status==="verified_close"||input.status==="verified_close_ready";
const closeDate=input.actual_closing_date||input.close_date||input.closing_date;
const closeDateValid=Boolean(closeDate)&&!Number.isNaN(new Date(closeDate).getTime());
const gross=Number(verified.gross_profit??input.gross_profit??input.assignment_fee);
const costs=Number(verified.closing_costs??input.closing_costs??input.total_costs??0);
const net=Number(verified.net_profit??input.net_profit??(Number.isFinite(gross)?gross-costs:NaN));
const profitValid=Number.isFinite(gross)&&Number.isFinite(costs)&&Number.isFinite(net);
const exitStrategy=input.exit_strategy||"assignment";
const negativeProfit=profitValid&&net<0;
let status="closeout_ready",nextWorkflow="WF-285",humanReview=false;
if(!identityComplete){status="blocked_missing_identity";nextWorkflow="WF-126";humanReview=true;}
else if(!verifiedClose){status="verified_close_required";nextWorkflow="WF-283";humanReview=true;}
else if(!closeDateValid||!profitValid){status="profit_or_close_data_invalid";nextWorkflow="WF-283";humanReview=true;}
else if(blockers.length){status="closeout_blocked";nextWorkflow="WF-126";humanReview=true;}
else if(negativeProfit){status="negative_profit_review";nextWorkflow="WF-126";humanReview=true;}
const profitRecord={deal_id:input.deal_id,lead_id:input.lead_id,property_id:input.property_id,close_id:input.close_id,close_date:closeDate,exit_strategy:exitStrategy,gross_profit:gross,closing_costs:costs,net_profit:net,profit_margin:gross!==0?net/gross:null,verified:true};
return [{json:{...input,workflow:"WF-284",workflow_name:"Verified Close → Final CRM Closeout, Assignment Profit Record & Portfolio Feedback Controller",status,profit_record:profitRecord,next_workflow:nextWorkflow,human_review_required:humanReview,audit:{event_type:"final_crm_closeout_profit_record",idempotency_key:input.idempotency_key||`wf-284:${input.deal_id||"unknown"}:${input.close_id||"none"}:${input.version||1}`}}}];
